static void phy_sysfs_create_links ( struct phy_device * phydev ) { struct net_device * dev = phydev -> attached_dev ; int err ; err = sysfs_create_link ( & phydev -> mdio . dev . kobj , & dev -> dev . kobj , "attached_dev" ) ; if ( err ) { return ; } err = sysfs_create_link_nowarn ( & dev -> dev . kobj , & phydev -> mdio . dev . kobj , "phydev" ) ; if ( err ) { dev_err ( & dev -> dev , "could not add device link to %s err %d\n" , kobject_name ( & phydev -> mdio . dev . kobj ) , err ) ; } phydev -> sysfs_links = true ; } 